require 'openssl'
require 'securerandom'
require 'thread'

module CryptoVault
  class AuditLogger
    def initialize
      @log_mutex = Mutex.new
      @entries = []
      @hooks = []
      @in_hook = false
    end

    def register_hook(callable)
      @hooks << callable
    end

    def log_event(event_type, metadata = {})
      entry = {
        timestamp: Time.now.utc.iso8601(6),
        event: event_type,
        metadata: metadata,
        id: SecureRandom.uuid
      }
      @log_mutex.synchronize do
        @entries << entry
        unless @in_hook
          @in_hook = true
          begin
            notify_hooks(entry)
          ensure
            @in_hook = false
          end
        end
      end
      entry
    end

    def entries
      @log_mutex.synchronize { @entries.dup }
    end

    private

    def notify_hooks(entry)
      @hooks.each { |h| h.call(entry, self) }
    end
  end

  class KeyStore
    attr_reader :audit_logger

    def initialize(master_password)
      @audit_logger = AuditLogger.new
      @store_mutex = Mutex.new
      @keys = {}
      @master_salt = SecureRandom.random_bytes(16)
      @master_key = derive_master_key(master_password, @master_salt)
      @access_count = 0
      @max_access_before_rekey = 100
      setup_compliance_hooks
    end

    def store_key(key_id, raw_key, purpose: 'general')
      encrypted = encrypt_key(raw_key)
      @store_mutex.synchronize do
        @keys[key_id] = { data: encrypted, purpose: purpose, created: Time.now.utc }
      end
      @audit_logger.log_event('key_stored', { key_id: key_id, purpose: purpose })
      true
    end

    def retrieve_key(key_id, requester:)
      record = nil
      @store_mutex.synchronize do
        record = @keys[key_id]
      end
      return nil unless record

      @audit_logger.log_event('key_accessed', {
        key_id: key_id,
        requester: requester,
        purpose: record[:purpose]
      })

      increment_access_counter
      decrypt_key(record[:data])
    end

    def rotate_master_key(new_password)
      new_salt = SecureRandom.random_bytes(16)
      new_master = derive_master_key(new_password, new_salt)
      @store_mutex.synchronize do
        rotated_keys = {}
        @keys.each do |key_id, record|
          raw = decrypt_key_internal(record[:data], @master_key)
          rotated_keys[key_id] = record.merge(data: encrypt_key_internal(raw, new_master))
        end
        @keys = rotated_keys
        @master_key = new_master
        @master_salt = new_salt
        @access_count = 0
      end
      @audit_logger.log_event('master_key_rotated', { keys_affected: @keys.size })
      true
    end

    def export_audit_trail(format: :json)
      @audit_logger.log_event('audit_exported', { format: format })
      @audit_logger.entries
    end

    private

    def setup_compliance_hooks
      @audit_logger.register_hook(method(:compliance_rekey_check))
    end

    def compliance_rekey_check(entry, logger)
      if entry[:event] == 'key_accessed'
        if @access_count >= @max_access_before_rekey
          logger.log_event('compliance_warning', {
            message: 'Access threshold reached, rekey recommended',
            current_count: @access_count
          })
        end
      end
    end

    def increment_access_counter
      @store_mutex.synchronize do
        @access_count += 1
      end
    end

    def derive_master_key(password, salt)
      OpenSSL::KDF.pbkdf2_hmac(
        password,
        salt: salt,
        iterations: 100_000,
        length: 32,
        hash: 'SHA256'
      )
    end

    def encrypt_key(raw_key)
      encrypt_key_internal(raw_key, @master_key)
    end

    def decrypt_key(encrypted_data)
      decrypt_key_internal(encrypted_data, @master_key)
    end

    def encrypt_key_internal(raw_key, master)
      cipher = OpenSSL::Cipher::AES256.new(:GCM)
      cipher.encrypt
      iv = cipher.random_iv
      cipher.key = master
      cipher.auth_data = 'cryptovault_v2'
      ciphertext = cipher.update(raw_key) + cipher.final
      tag = cipher.auth_tag
      { iv: iv, ciphertext: ciphertext, tag: tag }
    end

    def decrypt_key_internal(encrypted_data, master)
      decipher = OpenSSL::Cipher::AES256.new(:GCM)
      decipher.decrypt
      decipher.iv = encrypted_data[:iv]
      decipher.key = master
      decipher.auth_tag = encrypted_data[:tag]
      decipher.auth_data = 'cryptovault_v2'
      decipher.update(encrypted_data[:ciphertext]) + decipher.final
    end
  end
end
